script:
// Toggle (ds-metrics §5): title (body, el16 / el6 disabled) + switch, min height 44. The iOS DS wraps the system switch,
// so the geometry is Android SwitchPrimary's: 36×20 track (bg4 → accentPrimary), 16pt white knob inset 2. Knob and
// track animate implicitly (@motion.snappy / @motion.fast).
// Value — template events carry no payload, so:
//  • controlled: bind `on` to screen state and flip it in on.change (the new value is always the previous `!on`):
//      {"type": "Toggle", "props": {"title": "Push", "on": "=push"}, "on": {"change": "push = !push"}}
//  • uncontrolled: leave `on` unset — the toggle keeps instance state `local`; the screen only hears `change`.
param title: string = ""
param on: bool? = null
param enabled: bool = true
event change
state local = false
let isOn = on ?? local
// knob: white in both schemes (no onAccent token)
let knob = env.colorScheme == "dark" ? @color.el16 : @color.el1

on.tap:
if enabled {
  local = !isOn
  haptic("selection")
  emit change
}
